INSERT INTO knowledge_base (section_key, section_title, content, section_order) VALUES
('header', 'LBS College of Engineering, Kasaragod (LBSCEK)', E'# LBS College of Engineering, Kasaragod (LBSCEK)\n\nWebsite: https://lbscek.ac.in/', 0),

('general_information', '1. General Information', E'## 1. General Information\n- **Full Name:** Lal Bahadur Shastri College of Engineering, Kasaragod\n- **Established:** 1993\n- **Management:** L B S Centre for Science and Technology (Govt. of Kerala Undertaking)\n- **Location:** Povval, Muliyar P.O., Kasaragod, Kerala - 671542 (12 km from Kasaragod town)\n- **Campus Area:** 52 acres\n- **Affiliation:** APJ Abdul Kalam Technological University (KTU)\n- **Approval:** AICTE\n- **Contact:** +91-4994-256300, +91-4994-256301\n- **Email:** principal@lbscek.ac.in, office@lbscek.ac.in, admission@lbscek.ac.in\n- **Working Hours:** 9:00 AM - 4:30 PM (Class Timings: 9:15 AM - 4:00 PM)\n- **Office Hours:** 9:00 AM - 5:00 PM (Mon-Fri), 9:00 AM - 1:00 PM (Sat)', 1),

('leadership_administration', '2. Leadership & Administration', E'## 2. Leadership & Administration\n- **Principal:** Dr. Mohammad Shekoor T (Mechanical Dept) | Ph: 04994-250290\n- **Academic Dean (UG):** Dr. Praveen Kumar K (Professor, CSE) | Ph: 9447375156 | Email: praveenkodoth@lbscek.ac.in\n- **Student Affairs Dean (UG):** Dr. Vinodu George (Professor, CSE) | Ph: 9447386534 | Email: vinodu@lbscek.ac.in\n- **Administrative Officer:** Mr. Ajesh S\n- **Governing Body Chairman:** Sri. Pinarayi Vijayan (Hon. Chief Minister of Kerala)\n- **Governing Body Vice Chairperson:** Dr. R. Bindu (Hon. Minister for Higher Education)', 2),

('academic_programs', '3. Academic Programs', E'## 3. Academic Programs\n- **B.Tech Courses:** Computer Science (CSE), Electronics (ECE), Electrical (EEE), Mechanical (ME), Civil (CE), Information Technology (IT)\n- **M.Tech Specializations:** Computer Science & Engineering, VLSI Design, Power Systems, Thermal Engineering\n- **Postgraduate:** Master of Computer Applications (MCA)\n- **Annual Intake:** 480 (UG), 18 (PG - CSE)', 3),

('departments_faculty_detailed', '4. Departments & Faculty (Detailed)', E'## 4. Departments & Faculty (Detailed)\n### Computer Science & Engineering (CSE)\n- **HOD:** Dr. Manoj Kumar G (Professor) | Ph: 8547458075\n- **Professors:** Dr. Praveen Kumar K, Dr. Vinodu George, Dr. Jayalekshmi S\n- **Associate Professors:** Dr. Sulphikar A, Dr. Rahul C\n- **Assistant Professors:** Binoy D M Panikar, Safarunisa K M, Rajesh Kumar P M, Reema K V, Nishy Reshmi S, Lijin Das S, Krishnaprasad P K, Dr. Sarith Divakar M, Indu K B, Baby Sunitha V P, Fathimath Sameera M A, Vengayil Nayana Murali, Sajina K., Prathima A, Rasna P, Navami Aravind A, Geetha A V, Arathi S S, Sandra Mercelin\n\n### Information Technology (IT)\n- **HOD:** Dr. Anver S R (Professor)\n- **Professor:** Dr. Smithamol M B\n- **Assistant Professors:** Seena Thomas, Ayshath Sithara, Seetha Das V, Dhanyashree A S, Ramya P M, Sreejai, Nimitha Raj\n\n### Electronics & Communication (ECE)\n- **HOD:** Dr. Mary Reena K E (Professor)\n- **Professors:** Dr. Sheeba K, Dr. Pramod P\n- **Associate Professors:** Santo Mathew, Dr. Arathi T\n- **Assistant Professors:** Dr. Baiju P S, Dr. Anusree L, Dr. Anitha K, Zainaba Abdulrahiman, Vaishnavi T V\n\n### Electrical & Electronics (EEE)\n- **HOD:** Prof. Jayakumar M (Associate Professor)\n- **Professor:** Dr. Rajashree Raghavan\n- **Associate Professors:** Dr. Visalakshi V, Baby Sindhu A V, Dr. Aseem K\n- **Assistant Professors:** Dr. Sheeja V, Dr. Kannan M, Abhilash V Nair, Anish Joseph Jacob, Arun S Mathew, Mujeeb Rahuman, Seena K R\n\n### Mechanical Engineering (ME)\n- **HOD:** Dr. Manoj Kumar C V (Associate Professor)\n- **Associate Professors:** Mahesh P V, Dr. Swaraj Kumar B, Dr. Anil Kumar B C\n- **Assistant Professors:** Jowhar Mubarak, Vinod O M, Sreejith M, Prajina N V, Mukul Joseph, Latheesh Bharathan, Aswanth K, Kamaljith K\n\n### Civil Engineering (CE)\n- **HOD:** Dr. Anjali M S (Associate Professor)\n- **Assistant Professors:** Dr. Arun N R, Merlin R, Sruthi M, Sreevidya V, Jisha K V, Anjali M, Drisya M D, Athira Suresh, Sarga P Surendran\n\n### Applied Science\n- **HOD:** Prof. Vineesh Kumar K V (Mathematics)\n- **Mathematics Faculty:** Ramya M R, Smitha P, Rabiyathul Hadaviyya\n- **Chemistry Faculty:** Fathimath Ruksana A K, Dr. Dhanya Balan A P\n- **Physics Faculty:** Akhil Kumar A, Darshana N P\n- **Economics:** Jasir M H\n- **English:** Rajesh A, Vishnupriya V S\n- **Physical Education:** Prof. Joshua P Y', 4),

('fee_structure_202526_academic_year', '5. Fee Structure (2025-26 Academic Year)', E'## 5. Fee Structure (2025-26 Academic Year)\n### B.Tech Regular\n- **Merit Seat (Total):** ₹56,870/year\n- **SC/ST/OEC:** ₹1,000/year (Token amount)\n- **Fee Waiver (FW):** ₹18,620/year\n- **High Fee Seat:** ₹88,370/year\n\n### B.Tech Lateral Entry (LET)\n- **Merit Seat:** ₹49,200 + KTU Exam Fees\n- **Fee Waiver:** ₹10,950 + KTU Exam Fees\n\n### M.Tech\n- **Total Fee:** ₹44,880/year (College: ₹37,950 + KTU: ₹6,930)\n\n### Miscellaneous Fees (Included in Total)\n- **PTA Membership:** ₹5,000\n- **Union Fee:** ₹1,200\n- **Placement Fee:** ₹500\n- **Dept Association:** ₹1,000\n- **Sports Fund:** ₹250', 5),

('transportation_bus_routes_fees', '6. Transportation (Bus Routes & Fees)', E'## 6. Transportation (Bus Routes & Fees)\n- **Total Buses:** 6 (Melparamb, Kanhangad, Kasaragod, Periya, Pallikara, Nileshwaram)\n- **Bus Fees (Student/Year):**\n  - **Pallikkara:** ₹11,910 (Pickup 8:10 AM)\n  - **Bekal:** ₹11,180 (Pickup 8:15 AM)\n  - **Palakkunnu:** ₹10,530 (Pickup 8:20 AM)\n  - **Uduma:** ₹10,060 (Pickup 8:25 AM)\n  - **Kalanadu:** ₹9,420 (Pickup 8:30 AM)\n  - **Melparamba:** ₹8,960 (Pickup 8:35 AM)\n  - **Chaliyancode:** ₹8,580 (Pickup 8:40 AM)\n  - **Chemnad:** ₹8,500 (Pickup 8:45 AM)\n  - **Kasaragod:** ₹8,400 (Pickup 8:50 AM)\n  - **Vidya Nagar:** ₹5,630 (Pickup 8:55 AM)\n  - **Nalam Mile:** ₹4,530 (Pickup 9:00 AM)\n  - **Cherkala:** ₹3,420 (Pickup 9:05 AM)', 6),

('facilities_infrastructure', '7. Facilities & Infrastructure', E'## 7. Facilities & Infrastructure\n- **Central Library:** 25,000+ books, 5,000+ e-journals. Open 8:30 AM - 8:00 PM.\n- **Hostels:** Men''s (300 capacity) & Ladies'' "Shahanas" (200 capacity).\n- **Hostel Fees:** ~₹9,250 (General), ~₹2,250 (SC/ST).\n- **Computing:** 8 Labs, 400+ Systems, 1 Gbps NKN Connectivity.\n- **Sports:** Football ground, Cricket pitch, Indoor stadium, Gym.\n- **Other:** Canteen (South/North Indian), ATM (Central Bank), Co-operative Store, Medical Room, LBS Makerspace.', 7),

('placements', '8. Placements', E'## 8. Placements\n- **Highest Package:** ₹12 LPA (2023 Batch)\n- **Average Package:** ₹4.5 LPA\n- **Placement Rate:** 85% of eligible students\n- **Top Recruiters:** TCS, Infosys, Wipro, Cognizant, Tech Mahindra, Bosch, BYJU''S, Gadgeon', 8),

('student_clubs_iedc_technical', '9. Student Clubs (IEDC & Technical)', E'## 9. Student Clubs (IEDC & Technical)\n- **MULEARN:** Peer learning platform for skills.\n- **TINKERHUB:** Community for makers and innovators.\n- **FOSS CLUB:** Free and Open Source Software community.\n- **CYBER COMMUNITY:** Ethical hacking and cybersecurity.\n- **GALAXIA:** Space science and astronomy club.\n- **GDG on Campus:** Google Developer Group for Web/AI/Cloud.\n- **WOMEN TECH MAKERS (WTM):** Empowering women in technology.\n- **AWS CLOUD CLUB:** Amazon Web Services and cloud computing.\n- **KBA CHAPTER:** Kerala Blockchain Academy student chapter.\n- **CODERS CLUB:** Programming and problem-solving community.\n- **IEEE, CSI, ISTE, SAE:** Professional technical body chapters.', 9),

('admission_documents_required', '18. Admission & Documents Required', E'## 18. Admission & Documents Required\n- **Entrance Exam:** KEAM (Kerala Engineering Architecture Medical) score is mandatory for B.Tech.\n- **Eligibility:** 10+2 with minimum 50% marks in Physics, Chemistry, and Mathematics.\n- **Documents Checklist:**\n  - KEAM Rank Card & Admit Card.\n  - 10th & 12th Mark Sheets/Certificates.\n  - Transfer Certificate (TC) & Conduct Certificate.\n  - Passport size photos.\n  - Migration Certificate (if from boards other than Kerala State).\n- **NRI Admission:** Requires separate eligibility checks and additional documents.', 18),

('academic_regulations_discipline', '19. Academic Regulations & Discipline', E'## 19. Academic Regulations & Discipline\n- **Attendance:** Minimum 75% attendance required in each subject to appear for university exams.\n- **Dress Code:** Formal dress code is mandatory for students.\n- **Ragging:** Strictly prohibited. Criminal offence punishable by suspension/dismissal.\n- **Schedule:**\n  - Odd Semester: July - December.\n  - Even Semester: January - May.\n  - Summer Vacation: Typically May-June.', 19),

('specific_facility_details', '20. Specific Facility Details', E'## 20. Specific Facility Details\n- **Banking:**\n  - **Branch:** Central Bank of India (Campus Branch) is located near the Fluid Mechanics Lab but is **temporarily closed**.\n  - **ATM:** Available near the college main gate/entrance.\n- **Specialized Labs:**\n  - **Mechanical:** CAD/CAM Lab, Fluid Mechanics Lab, Workshop.\n  - **CSE/IT:** Networking Lab, Project Labs, Internet Lab.\n  - **Electronics:** DSP Lab, VLSI Lab.\n- **Library Staff:**\n  - **Librarian:** Mr. Vinod Kumar K T.\n  - **Librarian Grade IV:** Mrs. Beena Varghese.\n- **Physical Education:**\n  - **Assistant Professor:** Prof. Joshua P Y.', 20),

('student_projects_publications', '21. Student Projects & Publications', E'## 21. Student Projects & Publications\n- **Projects:**\n  - **Mini Project:** Conducted in the 3rd year.\n  - **Major Project:** Conducted in the final year.\n  - **Support:** Faculty guides assigned; labs available for extended hours.\n- **College Magazine:** Annual publication featuring student articles, poems, artwork, and academic achievements.\n- **Tech Fest:** ''TECHSURGE'' (Annual).\n- **Cultural Fest:** ''RHYTHM'' (Annual).', 21),

('detailed_location_context_for_navigation', '22. Detailed Location Context (For Navigation)', E'## 22. Detailed Location Context (For Navigation)\n- **"Where is the Mechanical Dept?"** -> Beside the football ground, along LBS Ground Road.\n- **"Where is the CSE Dept?"** -> Uphill from the main academic block, near the library and Shahanas hostel.\n- **"Where is the Canteen?"** -> Downhill from the main academic block.\n- **"Where is the PG Block?"** -> Near the Fluid Mechanics Lab and Central Bank building.\n- **"Where is the Makerspace?"** -> Near the Administrative building and Computer Lab.', 22),

('detailed_bus_fee_structure_staff_students', '23. Detailed Bus Fee Structure (Staff & Students)', E'## 23. Detailed Bus Fee Structure (Staff & Students)\n- **Pallikkara Route:**\n  - Student Fee: ₹11,910/year\n  - Staff Fee: ₹14,810/year\n- **Bekal Route:**\n  - Student Fee: ₹11,180/year\n  - Staff Fee: ₹13,860/year\n- **Palakkunnu Route:**\n  - Student Fee: ₹10,530/year\n  - Staff Fee: ₹13,130/year\n- **Uduma Route:**\n  - Student Fee: ₹10,060/year\n  - Staff Fee: ₹12,500/year\n- **Kalanadu Route:**\n  - Student Fee: ₹9,420/year\n  - Staff Fee: ₹11,660/year\n- **Melparamba Route:**\n  - Student Fee: ₹8,960/year\n  - Staff Fee: ₹11,240/year\n- **Chaliyancode Route:**\n  - Student Fee: ₹8,580/year\n  - Staff Fee: ₹10,710/year\n- **Chemnad Route:**\n  - Student Fee: ₹8,500/year\n  - Staff Fee: ₹10,290/year\n- **Kasaragod Route:**\n  - Student Fee: ₹8,400/year\n  - Staff Fee: ₹10,200/year\n- **Vidya Nagar Route:**\n  - Student Fee: ₹5,630/year\n  - Staff Fee: ₹6,930/year\n- **Nalam Mile Route:**\n  - Student Fee: ₹4,530/year\n  - Staff Fee: ₹5,570/year\n- **Cherkala Route:**\n  - Student Fee: ₹3,420/year\n  - Staff Fee: ₹4,200/year', 23),

('administrative_staff', '24. Administrative Staff', E'## 24. Administrative Staff\n- **Administrative Officer:** Mr. Ajesh S\n- **Senior Superintendent:** Mr. Santhosh Kumar K\n- **Junior Superintendent:** Mrs. Shaina Pacha\n- **Head Accountant:** Mr. Aneesh Mohan C S\n- **LBS Centre Member Secretary:** Prof. (Dr.) M. Abdul Rahiman\n- **Board of Governors Chairman:** Prof. M. Thamban Nair', 24),

('detailed_club_missions', '25. Detailed Club Missions', E'## 25. Detailed Club Missions\n- **MULEARN:** Innovative learning platform offering personalized educational experiences via adaptive technology.\n- **TINKERHUB:** Community of tinkerers and makers empowering people to innovate.\n- **FOSS CLUB:** Promotes "Free and Open Source Software"; focuses on learning, sharing, and contributing the open way.\n- **CYBER COMMUNITY:** Focuses on practical cybersecurity, ethical hacking, and responsible technology use.\n- **Microsoft Learn Student Ambassadors (MLSA):** Global initiative to empower students as campus leaders in tech (Azure, AI, Power Platform).\n- **CODERS CLUB:** The hub for programming; helps beginners take first steps and challenges advanced learners.\n- **GALAXIA:** Dedicated to space science, astronomy, and space technology.\n- **GDG on Campus:** Community for developers interested in Google technologies (Web, Mobile, Cloud, AI).\n- **KBA CHAPTER (Blockchain):** Official Kerala Blockchain Academy chapter; promotes awareness of decentralized technologies.\n- **WOW (Women of Wonder):** Inclusive space for women to voice ideas, showcase talents, and inspire positive change.\n- **AWS CLOUD CLUB:** Student-led community for learning Amazon Web Services and cloud computing.', 25),

('campus_landmarks_directions', '26. Campus Landmarks & Directions', E'## 26. Campus Landmarks & Directions\n- **Main Roads:** LBS Campus Road, LBS Ground Road, L.B.S Road.\n- **Academic Block:** Central building along LBS Campus Road.\n- **Football Ground:** Large open ground near the Mechanical Dept.\n- **Fluid Mechanics Lab:** Located along LBS Ground Road, near the PG Section.\n- **Central Bank Building:** Located near the Fluid Mechanics Lab (temporarily closed).\n- **Makerspace:** Located near the Administrative Building and Computer Lab.', 26),

('placement_training_specifics', '27. Placement Training Specifics', E'## 27. Placement Training Specifics\n- **Training Cell:** Dedicated Training & Placement Cell with a full-time coordinator.\n- **Programs:**\n  - Aptitude training.\n  - Technical workshops.\n  - Mock interviews.\n  - Group Discussion (GD) sessions.\n  - Guidance for GATE, CAT, GRE, TOEFL.\n- **Internships:** Facilitates summer internships with stipends in reputed companies.', 27),

('miscellaneous', '28. Miscellaneous', E'## 28. Miscellaneous\n- **Campus Banking:** While the branch is closed, fee payments are fully digital/online.\n- **Educational Loans:** Assistance provided for loan documentation.\n- **Insurance:** Student accident insurance coverage is provided.\n- **Health Camps:** Regular health check-up camps are organized.\n- **Counseling:** Mental health counseling services available for students.', 28),

('detailed_mtech_fee_breakdown_202526', '29. Detailed M.Tech Fee Breakdown (2025-26)', E'## 29. Detailed M.Tech Fee Breakdown (2025-26)\n- **Tuition Fee:** ₹24,000\n- **Caution Deposit (Refundable):** ₹5,000\n- **Establishment Charges:** ₹2,000\n- **Admission Fee:** ₹1,000\n- **Library Fee:** ₹1,000\n- **Professional Bodies Fee:** ₹1,000\n- **Online Academic Management Fee:** ₹450\n- **Special Fee:** ₹350\n- **KTU Fees:**\n  - Examination Fee: ₹4,300\n  - Administration Fee: ₹1,050\n  - Affiliation Fee: ₹1,050\n  - Arts & Sports Fee: ₹530', 29),

('lab_infrastructure_software', '30. Lab Infrastructure & Software', E'## 30. Lab Infrastructure & Software\n- **Licensed Software:** MATLAB, AutoCAD, ANSYS, Oracle.\n- **Lab Access:** 8:30 AM to 8:00 PM (open all days including weekends during project work).\n- **Internet:** High-speed internet via National Knowledge Network (NKN).\n- **Systems:** 400+ computers across 8 labs.', 30),

('hostel_living_amenities', '31. Hostel Living & Amenities', E'## 31. Hostel Living & Amenities\n- **Room Types:** Single, double, and triple sharing rooms available.\n- **Mess Details:** Separate vegetarian and non-vegetarian mess available.\n- **Cuisine:** North Indian and South Indian food options.\n- **Security:** 24/7 security, CCTV surveillance, and warden supervision.\n- **Visiting:** Parents can visit on weekends with prior permission.\n- **Facilities:** Wi-Fi, reading room, TV room, indoor games, gym, laundry.', 31),

('cultural_hobby_clubs_nontechnical', '32. Cultural & Hobby Clubs (Non-Technical)', E'## 32. Cultural & Hobby Clubs (Non-Technical)\n- **Music Club:** For musical talents and events.\n- **Dance Club:** Organizes dance performances and competitions.\n- **Drama Club:** Focuses on theater and acting.\n- **Fine Arts Club:** Promotes painting, sketching, and other arts.\n- **Literary Club:** For debates, writing, and literature.\n- **Photography Club:** For photography enthusiasts.\n- **Nature Club:** Focuses on environmental awareness and activities.\n- **Entrepreneurship Cell:** Foster startup culture.', 32),

('fee_payment_banking', '33. Fee Payment & Banking', E'## 33. Fee Payment & Banking\n- **Payment Mode:** Online payment available through the college portal.\n- **ATM:** Available near the college entrance.\n- **Bank Branch:** Central Bank of India (Campus Branch) - *Temporarily Closed*.\n- **Loans:** Assistance provided for educational loan documentation.', 33),

('campus_events_festivals', '34. Campus Events & Festivals', E'## 34. Campus Events & Festivals\n- **Tech Fest:** ''TECHSURGE'' - Annual technical festival featuring hackathons, coding competitions, and project exhibitions.\n- **Cultural Fest:** ''RHYTHM'' - Annual cultural festival for arts, music, dance, and drama.\n- **Sports Meet:** Annual sports meet and inter-collegiate tournaments.\n- **Department Days:** Specific celebrations organized by each engineering department.\n- **Project Exhibition:** Annual showcase of student major and mini projects.\n- **Observances:** Teachers'' day, Onam, Christmas, and Eid celebrations.', 34),

('womens_safety_empowerment', '35. Women''s Safety & Empowerment', E'## 35. Women''s Safety & Empowerment\n- **Committee:** Active Women''s Cell including female faculty and student representatives.\n- **Safety Measures:**\n  - Separate hostel blocks (Shahanas Hostel).\n  - Female attendants in college buses.\n  - 24/7 Security and CCTV surveillance.\n- **Activities:** Self-defense workshops, counseling sessions, and awareness programs.\n- **Grievance Redressal:** Confidential mechanism for addressing concerns.', 35),

('library_resources_detailed', '36. Library Resources (Detailed)', E'## 36. Library Resources (Detailed)\n- **Books:** Over 25,000 volumes.\n- **Journals:** 100+ print journals and 5,000+ e-journals.\n- **Digital Access:**\n  - DELNET (Developing Library Network).\n  - National Digital Library (NDL).\n  - IEEE Xplore digital library access.\n- **Facilities:** Reference section, reading rooms, digital library terminals, photocopying/reprographic services.', 36),

('sports_facilities_detailed', '37. Sports Facilities (Detailed)', E'## 37. Sports Facilities (Detailed)\n- **Main Stadium:** College main stadium on campus.\n- **Playground:** Large ground suitable for football and cricket.\n- **Indoor Stadium:** Multi-purpose facility for badminton, table tennis, and chess.\n- **Courts:** Volleyball and basketball courts available.\n- **Gymnasium:** Well-equipped gym with a trainer.\n- **Coaching:** Professional coaching available for major sports teams.', 37),

('ragging_prevention', '38. Ragging Prevention', E'## 38. Ragging Prevention\n- **Policy:** Zero Tolerance towards ragging.\n- **Helpline:** National Anti-Ragging Helpline 1800-180-5522.\n- **Committees:**\n  - Anti-Ragging Committee (Faculty & Administration).\n  - Anti-Ragging Squad (Monitors campus spots).\n- **Consequences:** Suspension or dismissal for perpetrators.\n- **Freshers:** Separate induction and orientation programs to ensure safety.', 38),

('campus_connectivity', '39. Campus Connectivity', E'## 39. Campus Connectivity\n- **Internet:** 1 Gbps backbone connectivity via NKN (National Knowledge Network).\n- **Wi-Fi:** Campus-wide access in academic blocks and hostels.\n- **Access:** Free for students and staff for academic purposes.\n- **Computer Center:** Central facility for browsing and research.', 39),

('history_of_expansion', '40. History of Expansion', E'## 40. History of Expansion\n- **Original Area:** Started with 20,000 sq.ft. of built-up area.\n- **Current Area:** Expanded to 2.5 lakh sq.ft.\n- **Land:** 52 acres provided by Plantation Corporation Kerala.\n- **Timeline:**\n  - 1993: Established.\n  - 1995: Moved to current campus.\n  - 2000: IT branch started.\n  - 2008: Civil Engineering branch started.\n  - 2013-15: PG programs (M.Tech) added.', 40),

('admission_categories', '41. Admission Categories', E'## 41. Admission Categories\n- **Government Quota:** Admission through KEAM counseling.\n- **Management Quota:** Available as per government norms.\n- **NRI Quota:** 15% seats reserved; requires separate application.\n- **Lateral Entry:** Direct second-year admission for Diploma holders.\n- **Special Reservations:** Sports quota, differently-abled quota (Saksham), and community-based reservations (SC/ST/OEC).', 41),

('useful_contacts_summary', '42. Useful Contacts (Summary)', E'## 42. Useful Contacts (Summary)\n- **Principal:** 04994-250290\n- **Office:** 04994-256300\n- **Fax:** 04994-256302\n- **Academic Dean (CSE):** 9447375156\n- **Student Affairs Dean:** 9447386534\n- **CSE HOD:** 8547458075', 42),

('governing_body_highlevel_administration', '43. Governing Body & High-Level Administration', E'## 43. Governing Body & High-Level Administration\n- **Chairman (Governing Body):** Sri. Pinarayi Vijayan (Hon. Chief Minister of Kerala)\n- **Vice Chairperson (Governing Body):** Dr. R. Bindu (Hon. Minister for Higher Education)\n- **Chairperson (Executive Committee):** Dr. Sharmila Mary Joseph IAS (Principal Secretary)\n- **Member Secretary (LBS Centre):** Prof. (Dr.) M. Abdul Rahiman\n- **Chairman (Board of Governors):** Prof. M. Thamban Nair', 43),

('detailed_miscellaneous_fee_breakdown_btech', '44. Detailed Miscellaneous Fee Breakdown (B.Tech)', E'## 44. Detailed Miscellaneous Fee Breakdown (B.Tech)\n- **Total Miscellaneous Fee:** ₹9,800 (One-time/Annual as applicable)\n- **PTA Membership Fee:** ₹5,000\n- **College Union Fee:** ₹1,200\n- **Department Association Fee:** ₹1,000\n- **Career Guidance & Placement Fee:** ₹500\n- **Co-operative Society (Kit + ID Card):** ₹1,650\n- **Sports Development Fund:** ₹250\n- **Series Examination Fee:** ₹200', 44),

('bus_pickup_schedule_morning', '45. Bus Pickup Schedule (Morning)', E'## 45. Bus Pickup Schedule (Morning)\n- **Pallikkara:** 8:10 AM\n- **Bekal:** 8:15 AM\n- **Palakkunnu:** 8:20 AM\n- **Uduma:** 8:25 AM\n- **Kalanadu:** 8:30 AM\n- **Melparamba:** 8:35 AM\n- **Chaliyancode:** 8:40 AM\n- **Chemnad:** 8:45 AM\n- **Kasaragod:** 8:50 AM\n- **Vidya Nagar:** 8:55 AM\n- **Nalam Mile:** 9:00 AM\n- **Cherkala:** 9:05 AM', 45),

('campus_navigation_landmarks', '46. Campus Navigation: Landmarks', E'## 46. Campus Navigation: Landmarks\n- **LBS Campus Road:** The main road running through the campus.\n- **Main Academic Block:** Located centrally along LBS Campus Road.\n- **Library:** Located "uphill" from the main academic block.\n- **CSE Department:** Located "uphill" near the Library and Shahanas Hostel.\n- **Canteen:** Located "downhill" from the main academic block.\n- **Mechanical Department:** Located beside the football ground along LBS Ground Road.\n- **Fluid Mechanics Lab:** Located along LBS Ground Road.\n- **PG Section:** Near the Fluid Mechanics Lab.', 46),

('iedc_club_descriptions_learning_making', '47. IEDC Club Descriptions: Learning & Making', E'## 47. IEDC Club Descriptions: Learning & Making\n- **MULEARN:** A peer learning platform using adaptive technology for personalized education.\n- **TINKERHUB:** A community of tinkerers and makers passionate about innovation.\n- **FOSS CLUB:** Promotes Free and Open Source Software, focusing on "learning, sharing, and contributing the open way."', 47),

('iedc_club_descriptions_coding_cyber', '48. IEDC Club Descriptions: Coding & Cyber', E'## 48. IEDC Club Descriptions: Coding & Cyber\n- **CYBER COMMUNITY:** Focuses on practical cybersecurity, ethical hacking, and responsible tech use; emphasizes "learning-by-doing."\n- **CODERS CLUB:** The hub for programming; helps beginners and challenges advanced learners with coding competitions.\n- **MSA (Microsoft Learn Student Ambassadors):** Provides access to Microsoft resources (Azure, AI) and mentorship to build campus leaders.', 48),

('iedc_club_descriptions_specialized_tech', '49. IEDC Club Descriptions: Specialized Tech', E'## 49. IEDC Club Descriptions: Specialized Tech\n- **GALAXIA:** The official space club dedicated to astronomy and space technology.\n- **GDG on Campus:** Google Developer Groups community for Web, Mobile, AI/ML, and Cloud technologies.\n- **AWS CLOUD CLUB:** Student-led community for learning Amazon Web Services and cloud computing.\n- **KBA CHAPTER:** Kerala Blockchain Academy chapter promoting decentralized technology awareness.', 49),

('iedc_club_descriptions_social_innovation', '50. IEDC Club Descriptions: Social & Innovation', E'## 50. IEDC Club Descriptions: Social & Innovation\n- **YIP CLUB:** Part of the Young Innovators Programme (K-DISC) to create solutions for sustainable development.\n- **WOW (Women of Wonder):** Empowers women through creativity, leadership, and social impact.\n- **WOMEN TECH MAKERS (WTM):** Google''s program to provide visibility and resources for women in technology.', 50),

('cse_faculty_list_complete', '51. CSE Faculty List (Complete)', E'## 51. CSE Faculty List (Complete)\n- **Professors:** Dr. Manoj Kumar G (HOD), Dr. Praveen Kumar K (Dean), Dr. Vinodu George (Dean), Dr. Jayalekshmi S.\n- **Associate Professors:** Dr. Sulphikar A, Dr. Rahul C.\n- **Assistant Professors:** Binoy D M Panikar, Safarunisa K M, Rajesh Kumar P M, Reema K V, Nishy Reshmi S, Lijin Das S, Krishnaprasad P K, Dr. Sarith Divakar M, Indu K B, Baby Sunitha V P, Fathimath Sameera M A, Vengayil Nayana Murali, Sajina K., Prathima A, Rasna P, Navami Aravind A, Geetha A V, Arathi S S, Sandra Mercelin.', 51),

('it_faculty_list_complete', '52. IT Faculty List (Complete)', E'## 52. IT Faculty List (Complete)\n- **HOD:** Dr. Anver S R (Professor).\n- **Professor:** Dr. Smithamol M B.\n- **Assistant Professors:** Seena Thomas, Ayshath Sithara, Seetha Das V, Dhanyashree A S, Ramya P M, Sreejai, Nimitha Raj.', 52),

('mechanical_faculty_list_complete', '53. Mechanical Faculty List (Complete)', E'## 53. Mechanical Faculty List (Complete)\n- **HOD:** Dr. Manoj Kumar C V (Associate Professor).\n- **Associate Professors:** Mahesh P V, Dr. Swaraj Kumar B, Dr. Anil Kumar B C.\n- **Assistant Professors:** Jowhar Mubarak, Vinod O M, Sreejith M, Prajina N V, Mukul Joseph, Latheesh Bharathan, Aswanth K, Kamaljith K.', 53),

('eee_faculty_list_complete', '54. EEE Faculty List (Complete)', E'## 54. EEE Faculty List (Complete)\n- **HOD:** Prof. Jayakumar M (Associate Professor).\n- **Professor:** Dr. Rajashree Raghavan.\n- **Associate Professors:** Dr. Visalakshi V, Baby Sindhu A V, Dr. Aseem K.\n- **Assistant Professors:** Dr. Sheeja V, Dr. Kannan M, Abhilash V Nair, Anish Joseph Jacob, Arun S Mathew, Mujeeb Rahuman, Seena K R.', 54),

('ece_faculty_list_complete', '55. ECE Faculty List (Complete)', E'## 55. ECE Faculty List (Complete)\n- **HOD:** Dr. Mary Reena K E (Professor).\n- **Professors:** Dr. Sheeba K, Dr. Pramod P.\n- **Associate Professors:** Santo Mathew, Dr. Arathi T.\n- **Assistant Professors:** Dr. Baiju P S, Dr. Anusree L, Dr. Anitha K, Zainaba Abdulrahiman, Vaishnavi T V.', 55),

('civil_faculty_list_complete', '56. Civil Faculty List (Complete)', E'## 56. Civil Faculty List (Complete)\n- **HOD:** Dr. Anjali M S (Associate Professor).\n- **Assistant Professors:** Dr. Arun N R, Merlin R, Sruthi M, Sreevidya V, Jisha K V, Anjali M, Drisya M D, Athira Suresh, Sarga P Surendran.', 56),

('applied_science_faculty_list_complete', '57. Applied Science Faculty List (Complete)', E'## 57. Applied Science Faculty List (Complete)\n- **Mathematics:** Prof. Vineesh Kumar K V (HOD), Ramya M R, Smitha P, Rabiyathul Hadaviyya.\n- **Chemistry:** Fathimath Ruksana A K, Dr. Dhanya Balan A P.\n- **Physics:** Akhil Kumar A, Darshana N P.\n- **Economics:** Jasir M H.\n- **English:** Rajesh A, Vishnupriya V S.', 57),

('office_library_staff', '58. Office & Library Staff', E'## 58. Office & Library Staff\n- **Administrative Officer:** Mr. Ajesh S.\n- **Senior Superintendent:** Mr. Santhosh Kumar K.\n- **Junior Superintendent:** Mrs. Shaina Pacha.\n- **Head Accountant:** Mr. Aneesh Mohan C S.\n- **Librarian:** Mr. Vinod Kumar K T.\n- **Librarian Grade IV:** Mrs. Beena Varghese.\n- **Physical Education:** Prof. Joshua P Y.', 58),

('detailed_hostel_fees', '59. Detailed Hostel Fees', E'## 59. Detailed Hostel Fees\n- **General Category:** ₹9,250 per year.\n- **Reserved Category (SC/ST/OEC):** ₹2,250 per year.\n- **Policy:** Hostel fees are optional and apply equally to Regular and Lateral Entry students.', 59),

('hostel_facilities_mess', '60. Hostel Facilities & Mess', E'## 60. Hostel Facilities & Mess\n- **Capacity:** 300 (Boys), 200 (Girls - Shahanas Hostel).\n- **Mess:** Separate Vegetarian and Non-Vegetarian mess halls.\n- **Food Type:** North Indian and South Indian dishes available.\n- **Amenities:** Wi-Fi, Gym, TV room, Indoor games, Laundry.\n- **Medical:** First aid facility and tie-ups with nearby hospitals.', 60),

('mtech_fee_components_detailed', '61. M.Tech Fee Components (Detailed)', E'## 61. M.Tech Fee Components (Detailed)\n- **Admission Fee:** ₹1,000\n- **Tuition Fee:** ₹24,000\n- **Special Fee:** ₹350\n- **Caution Deposit:** ₹5,000\n- **Establishment Charges:** ₹2,000\n- **Library Fees:** ₹1,000\n- **Professional Bodies:** ₹1,000\n- **Online Academic Mgmt:** ₹450\n- **KTU Exam Fee:** ₹4,300', 61),

('academic_calendar_timing', '62. Academic Calendar & Timing', E'## 62. Academic Calendar & Timing\n- **College Hours:** 9:00 AM to 4:30 PM (Mon-Fri).\n- **Class Hours:** 9:15 AM to 4:00 PM.\n- **Lunch Break:** 1:00 PM to 1:45 PM.\n- **Library (Weekdays):** 8:30 AM to 8:00 PM.\n- **Library (Saturday):** 8:30 AM to 5:00 PM.\n- **Library (Sunday):** 10:00 AM to 4:00 PM.\n- **Computer Center:** 8:30 AM to 8:00 PM (All days).', 62),

('admission_eligibility_process', '63. Admission Eligibility & Process', E'## 63. Admission Eligibility & Process\n- **B.Tech:** 10+2 with 50% in Physics, Chemistry, Maths + KEAM Rank.\n- **Lateral Entry:** Diploma holders eligible for 2nd year.\n- **NRI Quota:** 15% seats reserved; separate docs required.\n- **Documents:** KEAM Rank/Admit Card, 10th/12th Marksheets, TC, Conduct Cert, Photos.\n- **Application Dates:** KEAM usually opens Jan; Counseling June-July.', 63),

('scholarships_financial_aid', '64. Scholarships & Financial Aid', E'## 64. Scholarships & Financial Aid\n- **E-Grantz:** For SC/ST/OEC/SEBC categories.\n- **MCM Scholarship:** Merit-cum-Means for minority communities.\n- **Pragati Scholarship:** AICTE scheme for girls.\n- **Saksham Scholarship:** AICTE scheme for differently-abled.\n- **TFW:** Tuition Fee Waiver for meritorious low-income students.', 64),

('antiragging_measures', '65. Anti-Ragging Measures', E'## 65. Anti-Ragging Measures\n- **Policy:** Zero Tolerance.\n- **Helpline:** 1800-180-5522.\n- **Squad:** Faculty squads monitor the campus.\n- **Surveillance:** CCTV monitoring active.\n- **Action:** Suspension or dismissal for offenders.', 65),

('womens_welfare', '66. Women''s Welfare', E'## 66. Women''s Welfare\n- **Women''s Cell:** Conducts awareness, self-defense workshops, counseling.\n- **Transport:** Female attendants present in girls'' buses.\n- **Safety:** Secure ladies hostel (Shahanas) with 24/7 security.', 66),

('history_infrastructure_growth', '67. History & Infrastructure Growth', E'## 67. History & Infrastructure Growth\n- **Established:** 1993 (Temporary building), 1995 (Current campus).\n- **Land:** 52 acres given by Plantation Corporation Kerala at Povval.\n- **Expansion:** Started with 20,000 sq.ft.; now 2.5 lakh sq.ft.\n- **Affiliation Change:** Calicut U (1993-96) -> Kannur U (1996-2015) -> KTU (2015-Present).', 67),

('placements_training', '68. Placements & Training', E'## 68. Placements & Training\n- **Placement Cell:** Full-time coordinator available.\n- **Training:** Aptitude, Technical, Mock Interviews, GD sessions.\n- **Stats:** 85% placement rate; Highest Package ₹12 LPA; Avg ₹4.5 LPA.\n- **Recruiters:** TCS, Infosys, Wipro, Cognizant, Tech Mahindra, Bosch, BYJU''S.\n- **Higher Studies:** Guidance for GATE, CAT, GRE, TOEFL.', 68),

('sports_fitness_details', '69. Sports & Fitness Details', E'## 69. Sports & Fitness Details\n- **Main Ground:** Football & Cricket.\n- **Indoor Stadium:** Badminton, Table Tennis, Chess.\n- **Gym:** Well-equipped with trainer.\n- **Courts:** Volleyball, Basketball.\n- **Events:** Annual Sports Meet, Inter-collegiate tournaments.', 69),

('library_resources', '70. Library Resources', E'## 70. Library Resources\n- **Books:** 25,000+ volumes.\n- **Journals:** 100+ print, 5000+ e-journals.\n- **Digital:** DELNET, NDL, IEEE Xplore access.\n- **Services:** Reference, Circulation, Reprography (Photocopy).', 70),

('campus_connectivity_wifi', '71. Campus Connectivity', E'## 71. Campus Connectivity\n- **Internet:** 1 Gbps via NKN (National Knowledge Network).\n- **Wi-Fi:** Available in academic blocks and hostels.\n- **Access:** Free for academic purposes.', 71),

('student_projects', '72. Student Projects', E'## 72. Student Projects\n- **Mini Project:** 3rd Year.\n- **Major Project:** Final Year.\n- **Funding:** Support for innovative projects.\n- **Exhibition:** Annual project exhibition.', 72),

('canteen_details', '73. Canteen Details', E'## 73. Canteen Details\n- **Location:** Downhill from Academic Block.\n- **Timings:** 8:00 AM to 5:00 PM.\n- **Menu:** Breakfast, Lunch, Snacks (Veg & Non-Veg).\n- **Pricing:** Subsidized rates for students/staff.', 73),

('cooperative_store', '74. Co-operative Store', E'## 74. Co-operative Store\n- **Items:** Textbooks, Practical Records, Drawing Instruments, Stationery.\n- **Services:** Photostat, Binding.\n- **Rates:** Discounted for students.', 74),

('medical_facilities', '75. Medical Facilities', E'## 75. Medical Facilities\n- **On-Campus:** First aid room with trained nurse.\n- **Off-Campus:** Tie-ups with nearby hospitals for emergencies.\n- **Insurance:** Student accident insurance provided.', 75),

('banking', '76. Banking', E'## 76. Banking\n- **ATM:** Near college entrance.\n- **Branch:** Central Bank of India (Campus Branch) - Temporarily Closed.\n- **Digital:** All fee payments are online.', 76),

('cultural_activities', '77. Cultural Activities', E'## 77. Cultural Activities\n- **Festivals:** ''RHYTHM'' (Cultural), ''TECHSURGE'' (Technical).\n- **Clubs:** Music, Dance, Drama, Fine Arts, Literary, Photography, Nature.\n- **Magazine:** Annual college magazine published.', 77),

('entrepreneurship_iedc', '78. Entrepreneurship (IEDC)', E'## 78. Entrepreneurship (IEDC)\n- **Cell:** Entrepreneurship Development Cell (EDC).\n- **Activities:** Workshops, Business Plan Competitions, Mentoring.\n- **Incubation:** Guidance for funding and startups.', 78),

('alumni_association', '79. Alumni Association', E'## 79. Alumni Association\n- **Name:** LBSCEKAA.\n- **Network:** Alumni in Google, Microsoft, Amazon, etc.\n- **Contribution:** Scholarships, placement support, guest lectures.', 79),

('research', '80. Research', E'## 80. Research\n- **PhD Centers:** CSE and Mechanical Engineering departments.\n- **Focus:** Active research in engineering/tech; funded projects.', 80),

('transport_fee_comparison', '81. Transport: Fee Comparison', E'## 81. Transport: Fee Comparison\n- **Pallikkara:** Student ₹11,910 vs Staff ₹14,810.\n- **Kasaragod:** Student ₹8,400 vs Staff ₹10,200.\n- **Cherkala:** Student ₹3,420 vs Staff ₹4,200.', 81),

('btech_fee_variations', '82. B.Tech Fee Variations', E'## 82. B.Tech Fee Variations\n- **Merit Seat:** ₹56,870.\n- **High Fee Seat:** ₹88,370.\n- **Lateral Entry (Merit):** ₹49,200.\n- **Lateral Entry (FW):** ₹10,950.', 82),

('nearby_tourist_spots', '83. Nearby Tourist Spots', E'## 83. Nearby Tourist Spots\n- **Bekal Fort:** ~45 km.\n- **Kappil Beach:** ~35 km.\n- **Madhur Temple:** ~25 km.\n- **Parappa Wildlife:** ~50 km.', 83),

('makerspace_details', '84. Makerspace Details', E'## 84. Makerspace Details\n- **Location:** Near Admin Block/Computer Lab.\n- **Purpose:** Innovation, prototyping, project work.\n- **Equipment:** Tools for electronics and mechanical projects.', 84),

('bus_garage', '85. Bus Garage', E'## 85. Bus Garage\n- **Location:** Parking area along LBS Campus Road.\n- **Usage:** Parking for the 6 college buses.', 85),

('pg_section_building', '86. PG Section Building', E'## 86. PG Section Building\n- **Location:** Near Fluid Mechanics Lab / Central Bank.\n- **Programs:** Houses MCA and other PG courses.', 86),

('holidays', '87. Holidays', E'## 87. Holidays\n- **Type:** Follows Kerala Government and University holidays.\n- **Major:** Onam, Christmas, Eid.\n- **Vacation:** Summer break typically in May-June.', 87),

('dress_code', '88. Dress Code', E'## 88. Dress Code\n- **Requirement:** Formal dress code mandated for students.\n- **Focus:** Maintaining academic decorum.', 88),

('attendance', '89. Attendance', E'## 89. Attendance\n- **Requirement:** Minimum 75% per subject required for exams.\n- **Discipline:** Strictly monitored.', 89),

('contact_emails', '90. Contact Emails', E'## 90. Contact Emails\n- **Principal:** principal@lbscek.ac.in\n- **Office:** office@lbscek.ac.in\n- **Admissions:** admission@lbscek.ac.in', 90),

('cse_dean_contacts', '91. CSE Dean Contacts', E'## 91. CSE Dean Contacts\n- **Academic Dean:** Dr. Praveen Kumar K (9447375156).\n- **Student Affairs Dean:** Dr. Vinodu George (9447386534).', 91),

('cse_hod_contact', '92. CSE HOD Contact', E'## 92. CSE HOD Contact\n- **Name:** Dr. Manoj Kumar G.\n- **Phone:** 8547458075.\n- **Email:** manojkumar@lbscek.ac.in', 92),

('faculty_qualifications', '93. Faculty Qualifications', E'## 93. Faculty Qualifications\n- **Level:** 90% of faculty hold M.Tech or Ph.D degrees.\n- **Experience:** Average 10+ years teaching experience.', 93),

('vision_statement', '94. Vision Statement', E'## 94. Vision Statement\n- **Text:** "To become a paragon institution for pursuance of Education and Research in Engineering and Technology."', 94),

('mission_statement', '95. Mission Statement', E'## 95. Mission Statement\n- **Point 1:** Impart finest quality Technical Education & Training.\n- **Point 2:** Nurture a vision of Sustainable development.\n- **Point 3:** Bequeath it to the next generation of professionals.', 95),

('industry_collaborations', '96. Industry Collaborations', E'## 96. Industry Collaborations\n- **Goal:** Enhance practical exposure, internships, and placements.\n- **Areas:** Software, Mechanical, Electronics.\n- **Activities:** Guest lectures, industrial visits.', 96),

('student_editorial_board', '97. Student Editorial Board', E'## 97. Student Editorial Board\n- **Role:** Manages the annual college magazine.\n- **Guidance:** Faculty guided.', 97),

('safety_for_freshers', '98. Safety for Freshers', E'## 98. Safety for Freshers\n- **Program:** Separate induction and orientation.\n- **Monitoring:** Anti-ragging squad active.', 98),

('digital_library', '99. Digital Library', E'## 99. Digital Library\n- **Access:** 24/7 online resource access.\n- **Content:** Journals, papers, e-books.', 99),

('fee_payment_method', '100. Fee Payment Method', E'## 100. Fee Payment Method\n- **Method:** Online payment through college portal.\n- **Cash:** Generally not accepted for main fees (Digital campus).', 100),

('common_titles_honorifics_malayalam', '101. Common Titles / Honorifics (Malayalam)', E'## 101. Common Titles / Honorifics (Malayalam)\n- **ശ്രീ (Sri):** ശ്രീമാൻ (Mr.) - Respectful title for men\n- **ശ്രീമതി (Smt.):** വിവാഹിതയായ സ്ത്രീ (Mrs.) - Married woman\n- **കു. (Kum.):** കുമാരി (Miss) - Unmarried woman\n- **ഡോ. (Dr.):** ഡോക്ടർ (Doctor)\n- **പ്രൊ. (Prof.):** പ്രൊഫസർ (Professor)\n- **അഡ്വ. (Adv.):** അഡ്വക്കേറ്റ് (Advocate / Lawyer)\n- **ഇം. / എഞ്ചി. (Eng.):** എഞ്ചിനീയർ (Engineer)\n- **ശ്രീമാൻ / ശ്രീമതി:** Respectful forms used before names', 101),

('degree_course_abbreviations', '102. Degree & Course Abbreviations', E'## 102. Degree & Course Abbreviations\n- **B.Tech:** Bachelor of Technology\n- **B.E:** Bachelor of Engineering\n- **M.Tech:** Master of Technology\n- **MCA:** Master of Computer Applications\n- **Diploma:** Polytechnic Diploma', 102),

('branch_abbreviations_very_common', '103. Branch Abbreviations (Very Common)', E'## 103. Branch Abbreviations (Very Common)\n- **CSE:** Computer Science & Engineering\n- **CS:** Computer Science\n- **IT:** Information Technology\n- **ECE:** Electronics & Communication Engineering\n- **EEE:** Electrical & Electronics Engineering\n- **ME:** Mechanical Engineering\n- **CE:** Civil Engineering\n- **AI:** Artificial Intelligence\n- **AI & DS:** Artificial Intelligence & Data Science\n- **ML:** Machine Learning\n- **Robotics:** Robotics Engineering', 103),

('college_academic_terms', '104. College / Academic Terms', E'## 104. College / Academic Terms\n- **HOD:** Head of Department\n- **HoI / Principal:** Head of Institution\n- **FY:** First Year\n- **SY:** Second Year\n- **TY:** Third Year\n- **Final Year:** Fourth Year\n- **Sem:** Semester\n- **Lab:** Laboratory\n- **Intern:** Internship\n- **Project:** Final Year Project\n- **Credits:** Academic credit points', 104),

('exams_evaluation_terms', '105. Exams & Evaluation Terms', E'## 105. Exams & Evaluation Terms\n- **IA:** Internal Assessment\n- **CIA:** Continuous Internal Assessment\n- **End Sem / ES:** End Semester Exam\n- **KT / ATKT:** Keep Term / Allowed To Keep Term\n- **CGPA:** Cumulative Grade Point Average\n- **SGPA:** Semester Grade Point Average\n- **Backlog:** Failed subject that needs to be cleared', 105),

('training_placement_terms', '106. Training & Placement Terms', E'## 106. Training & Placement Terms\n- **T&P:** Training & Placement\n- **CRT:** Campus Recruitment Training\n- **Internship:** Industrial Training\n- **PPO:** Pre-Placement Offer\n- **On-Campus:** Placement through college\n- **Off-Campus:** Placement outside college', 106),

('latest_news_updates_as_of_february_2026', '107. Latest News & Updates (as of February 2026)', E'## 107. Latest News & Updates (as of February 2026)\n- **College Union Election 2025-26:** Election to College Union scheduled for **February 20, 2026**. University Notification dated 08-02-2026. Refer to University Statute, Election Manual, and Lyngdoh Committee Report for details. More info: https://lbscek.ac.in/election-to-college-union-2/\n- **Quotations & Tenders:** Sealed competitive quotations invited for supply of equipment to Microprocessor lab (Jan 2026).\n- **Mobile Passport Seva:** Mobile Passport Seva camp conducted at college (Sep 2025).\n- **Newly Introduced Courses:** New courses introduced for 2025-26 academic year (Aug 2025).\n- **Non KEAM Admission 2025:** Spot admissions open for Non-KEAM candidates (Aug 2025).\n- **Kerala Govt 5th 100 Days Programme:** Five major projects inaugurated at LBSCEK by Higher Education Minister (Jun 2025).\n- **M.Tech Sponsored Seats:** Applications invited for M.Tech sponsored seats 2025-26 (May 2025).\n- **SigmaPower:** EEE department event for aspiring engineering students (May 2025).\n- **NRI Admission 2025:** Applications for B.Tech NRI seats in Civil, Mechanical, EEE, ECE (May 2025).\n- **Government Educational Institution Status:** LBSCEK officially granted Government Educational Institution status by Kerala Government (May 2025).\n- **KEAM Mock Test 2025:** Free KEAM mock test conducted at college (Mar 2025).\n- **Deepa Memorial Hall:** EEE Seminar Hall renamed as Deepa Memorial Hall (Dec 2025).\n- **FDP on AI in VLSI:** Faculty Development Program on "Exploring the Opportunities of AI in VLSI Systems" by ECE Dept (Nov 2025).\n- **IEDC Summit ''25:** IEDC Summit tender notice (Nov 2025).\n- **News Source:** https://lbscek.ac.in/news-and-updates/', 107),

('website_directory_official_pages_links', '108. Website Directory (Official Pages & Links)', E'## 108. Website Directory (Official Pages & Links)\n### Institution\n- **Homepage:** https://lbscek.ac.in/\n- **About Us:** https://lbscek.ac.in/about-us/\n- **College Map:** https://lbscek.ac.in/college-map/\n- **Mandatory Disclosure:** https://lbscek.ac.in/mandatory-disclosure/\n- **AICTE Orders:** https://lbscek.ac.in/aicte-orders/\n- **NBA Accreditation Process:** https://lbscek.ac.in/nba-accreditation-process/\n- **Special Rule:** https://lbscek.ac.in/special-rule/\n- **Audit Reports:** https://lbscek.ac.in/audit-reports/\n- **Student Verification:** https://lbscek.ac.in/student-verification/\n- **Quotations & Tenders:** https://lbscek.ac.in/quotations-and-tenders/\n- **Anti Ragging Cell:** https://lbscek.ac.in/anti-ragging-cell/\n- **AICTE Online Skill Test:** https://lbscek.ac.in/aicte-online-skill-test/\n- **AICTE Feedback:** https://lbscek.ac.in/aicte-feedback/\n- **Grievance Cell:** https://lbscek.ac.in/grievance-cell/\n\n### Administration\n- **Board of Governors:** https://lbscek.ac.in/board-of-governors/\n- **Director:** https://lbscek.ac.in/director/\n- **Principal:** https://lbscek.ac.in/principal/\n- **UG Dean:** https://lbscek.ac.in/ug-dean/\n- **Dean Research & Development:** https://lbscek.ac.in/dean-research-development/\n- **Internal Compliance Committee:** https://lbscek.ac.in/internal-compliance-committee/\n- **IQAC:** https://lbscek.ac.in/internal-quality-assurance-cell-iqac/\n- **Administrative Wing:** https://lbscek.ac.in/administrative-wing/\n- **Right to Information (RTI):** https://lbscek.ac.in/right-to-information/\n\n### Admission\n- **Admission Process:** https://lbscek.ac.in/admission-procedure/\n- **KEAM Admission:** https://lbscek.ac.in/admission-keam/\n- **NRI Scheme:** https://lbscek.ac.in/nri-scheme/\n- **Lateral Entry Scheme:** https://lbscek.ac.in/lateral-entry-scheme/\n- **Non-KEAM Admission:** https://lbscek.ac.in/non-keam-admission/\n- **Fee Waiver Scheme:** https://lbscek.ac.in/fee-waiver-scheme/\n- **Fee Structure:** https://lbscek.ac.in/fee-structure/\n\n### Academics\n- **Departments Overview:** https://lbscek.ac.in/departments/\n- **Programs Overview:** https://lbscek.ac.in/programs/\n- **Syllabus:** https://lbscek.ac.in/syllabus/\n- **Academic Calendar:** https://lbscek.ac.in/academic-calendar/\n- **Downloads:** https://lbscek.ac.in/downloads/\n\n### Departments\n- **CSE:** https://lbscek.ac.in/computer-science-engineering-2/\n- **Mechanical Engineering:** https://lbscek.ac.in/mechanical-engineering/\n- **EEE:** https://lbscek.ac.in/electrical-electronics-engineering/\n- **ECE:** https://lbscek.ac.in/electronics-communication-engineering/\n- **Civil Engineering:** https://lbscek.ac.in/civil-engineering/\n- **Applied Science:** https://lbscek.ac.in/applied-science/\n- **Physical Education:** https://lbscek.ac.in/physical-education/\n\n### Activities & Organizations\n- **CGPU (Career Guidance):** https://lbscek.ac.in/career-guidance-placement-unit-cgpu/\n- **Alumni Association:** https://lbscek.ac.in/alumni-association/\n- **NSS:** https://lbscek.ac.in/national-service-scheme/\n- **PTA:** https://lbscek.ac.in/parent-teacher-association/\n- **Continuing Education Cell:** https://lbscek.ac.in/continuing-education-cell/\n- **IEDC:** https://lbscek.ac.in/iedc/\n- **Industry Institute Interaction:** https://lbscek.ac.in/industry-institute-interaction/\n- **IEEE:** https://lbscek.ac.in/ieee/\n- **College Union:** https://lbscek.ac.in/college-union/\n\n### Facilities\n- **Central Library:** https://lbscek.ac.in/central-library/\n- **Digital Library:** https://lbscek.ac.in/digital-library/\n- **Central Computing Facility:** https://lbscek.ac.in/central-computing-facility/\n- **AICTE IDEA Lab:** https://lbscek.ac.in/aicte-idea-lab/\n- **Hostel:** https://lbscek.ac.in/hostel/\n- **Bus Service:** https://lbscek.ac.in/bus-service/\n- **ATM Facility:** https://lbscek.ac.in/atm-facility/\n- **Student Co-Operative Society:** https://lbscek.ac.in/student-co-operative-society/\n- **Fab Lab Facility:** https://lbscek.ac.in/fab-lab-facility/\n- **Skill Delivery Platform:** https://lbscek.ac.in/skill-delivery-platform/\n\n### Fee Payment\n- **Annual/Admission Fee:** https://lbscek.ac.in/annual-admission-fee/\n- **Exam/Other Fee Payment:** https://lbscek.ac.in/exam-other-fee-payment/\n- **Semester Registration Online:** https://lbscek.ac.in/semester-registration-online/\n- **Hostel Rent:** https://lbscek.ac.in/hostel-rent/\n\n### Contact\n- **Contact Us:** https://lbscek.ac.in/contact-2/', 108),

('academic_performance_results', '109. Academic Performance & Results', E'## 109. Academic Performance & Results\n- **University Exam Results:** Published by APJ Abdul Kalam Technological University (KTU)\n- **Result Access:** Available through KTU portal and college website\n- **Revaluation:** Students can apply for revaluation within specified dates\n- **Grade System:** CGPA-based evaluation system (10-point scale)\n- **Pass Percentage:** Consistently above 85% across departments\n- **Toppers:** Department toppers recognized annually with awards', 109),

('examination_cell', '110. Examination Cell', E'## 110. Examination Cell\n- **Hall Ticket:** Distributed before each semester exam\n- **Exam Schedule:** Published 2 weeks before exams\n- **Malpractice:** Strict action taken as per university rules\n- **Supplementary Exams:** Conducted for failed subjects\n- **Series Tests:** Conducted regularly (3-4 per semester)\n- **Model Exams:** Conducted before university exams', 110),

('research_development_cell', '111. Research & Development Cell', E'## 111. Research & Development Cell\n- **Dean R&D:** Dr. [Name] (Contact via college)\n- **Focus Areas:** AI/ML, IoT, Renewable Energy, Automation\n- **Funded Projects:** Multiple AICTE/DST/KSCSTE funded projects\n- **Publications:** Faculty publish in SCI/Scopus indexed journals\n- **Conferences:** Students encouraged to present papers\n- **Patent Filing:** Support provided for innovative ideas', 111),

('international_collaborations', '112. International Collaborations', E'## 112. International Collaborations\n- **MOUs:** With foreign universities for student exchange\n- **Study Abroad:** Guidance for GRE/TOEFL/IELTS\n- **Virtual Exchange:** Online collaboration with international institutions\n- **Foreign Faculty:** Occasional visiting faculty from abroad', 112),

('startup_ecosystem', '113. Startup Ecosystem', E'## 113. Startup Ecosystem\n- **IEDC Activities:** Regular bootcamps, ideathons, pitch sessions\n- **Funding Support:** Guidance for KSUM/IEDC funding\n- **Incubation:** Pre-incubation support available on campus\n- **Success Stories:** Alumni-founded startups in various sectors\n- **Mentorship:** Industry mentors assigned to startup teams', 113),

('social_outreach_programs', '114. Social Outreach Programs', E'## 114. Social Outreach Programs\n- **NSS Activities:**\n    - Blood donation camps\n    - Village adoption programs\n    - Literacy drives\n    - Environmental awareness campaigns\n- **Community Service:** Regular visits to orphanages, old age homes\n- **Disaster Relief:** Active participation during floods/calamities', 114),

('environmental_initiatives', '115. Environmental Initiatives', E'## 115. Environmental Initiatives\n- **Green Campus:** Tree plantation drives regularly conducted\n- **Waste Management:** Segregation of waste (wet/dry/e-waste)\n- **Solar Power:** Solar panels installed in select buildings\n- **Rain Water Harvesting:** Systems installed across campus\n- **Plastic-Free Campus:** Single-use plastic banned\n- **Energy Conservation:** Awareness programs conducted', 115),

('student_counseling_mental_health', '116. Student Counseling & Mental Health', E'## 116. Student Counseling & Mental Health\n- **Professional Counselor:** Available on specific days\n- **Confidential Sessions:** One-on-one counseling provided\n- **Peer Support:** Student volunteers trained for basic support\n- **Workshops:** Stress management, time management sessions\n- **Crisis Helpline:** Contact numbers available 24/7', 116),

('skill_development_programs', '117. Skill Development Programs', E'## 117. Skill Development Programs\n- **Technical Training:**\n    - Python, Java, C++ programming\n    - Web development (HTML, CSS, JS, React)\n    - Mobile app development (Android/iOS)\n    - Cloud computing (AWS, Azure)\n    - Data Science & Analytics\n- **Soft Skills:**\n    - Communication skills\n    - Presentation skills\n    - Leadership training\n    - Teamwork & collaboration\n- **Aptitude Training:** Quantitative, Logical, Verbal\n- **Foreign Language:** Basic courses in German/French', 117),

('industrial_training_visits', '118. Industrial Training & Visits', E'## 118. Industrial Training & Visits\n- **Industrial Visits:** Organized for all departments annually\n- **Companies Visited:** Major companies in respective domains\n- **In-Plant Training:** Mandatory training during vacations\n- **Duration:** 2-4 weeks typically\n- **Documentation:** Report submission and presentation required', 118),

('professional_body_memberships', '119. Professional Body Memberships', E'## 119. Professional Body Memberships\n- **IEEE Student Chapter:** Active with regular events\n- **CSI (Computer Society of India):** Student chapter operational\n- **ISTE (Indian Society for Technical Education):** Faculty & student members\n- **SAE (Society of Automotive Engineers):** For Mechanical students\n- **IEI (Institution of Engineers India):** Corporate/student members\n- **IETE (Institution of Electronics):** For ECE/EEE students', 119),

('laboratory_facilities_detailed_by_department', '120. Laboratory Facilities (Detailed by Department)', E'## 120. Laboratory Facilities (Detailed by Department)\n- **CSE/IT Labs:**\n    - Programming Lab (C, C++, Java)\n    - Data Structures Lab\n    - Database Management Lab\n    - Computer Networks Lab\n    - Operating Systems Lab\n    - Web Technology Lab\n    - Software Engineering Lab\n    - Project Lab\n- **ECE Labs:**\n    - Electronics Workshop\n    - Digital Electronics Lab\n    - Microprocessor & Microcontroller Lab\n    - Communication Systems Lab\n    - VLSI Design Lab\n    - DSP Lab\n    - Embedded Systems Lab\n- **EEE Labs:**\n    - Electrical Machines Lab\n    - Power Systems Lab\n    - Control Systems Lab\n    - Power Electronics Lab\n    - Measurements & Instrumentation Lab\n    - High Voltage Engineering Lab\n- **Mechanical Labs:**\n    - Workshop (Fitting, Welding, Machining)\n    - Fluid Mechanics Lab\n    - Thermal Engineering Lab\n    - Strength of Materials Lab\n    - CAD/CAM Lab\n    - Metrology Lab\n    - Dynamics Lab\n- **Civil Labs:**\n    - Surveying Lab\n    - Concrete & Highway Materials Lab\n    - Soil Mechanics Lab\n    - Structural Analysis Lab\n    - Environmental Engineering Lab\n    - CAD Lab', 120),

('student_achievement_recognition', '121. Student Achievement Recognition', E'## 121. Student Achievement Recognition\n- **Merit Certificates:** For academic excellence\n- **Sports Achievements:** Recognized at university/state/national level\n- **Technical Competitions:** Winners felicitated\n- **Cultural Events:** Best performers awarded\n- **Leadership Awards:** For union/club office bearers\n- **Best Outgoing Student:** Annual award', 121),

('parent_engagement', '122. Parent Engagement', E'## 122. Parent Engagement\n- **PTA Meetings:** Conducted twice per semester\n- **Progress Reports:** Shared with parents regularly\n- **Parent Portal:** Online access to attendance, marks\n- **Grievance Redressal:** Parents can raise concerns\n- **Parental Consent:** Required for industrial visits, tours', 122),

('discipline_code_of_conduct', '123. Discipline & Code of Conduct', E'## 123. Discipline & Code of Conduct\n- **Identity Card:** Mandatory to wear on campus\n- **Attendance Marking:** Biometric/manual system\n- **Late Coming:** Penalized after grace period\n- **Unauthorized Absence:** Requires prior permission\n- **Dress Code Violations:** Warning/disciplinary action\n- **Ragging:** Zero tolerance; criminal case filed\n- **Substance Abuse:** Strictly prohibited; leads to expulsion', 123),

('semesterwise_activities_typical_calendar', '124. Semester-wise Activities (Typical Calendar)', E'## 124. Semester-wise Activities (Typical Calendar)\n- **Semester 1 (July-December):**\n    - Induction program for first years\n    - Onam celebrations (Aug/Sep)\n    - Technical fest participation\n    - Series tests (Sep, Oct, Nov)\n    - End semester exams (Nov/Dec)\n- **Semester 2 (January-May):**\n    - Republic Day celebrations (Jan)\n    - Department days\n    - Cultural fest RHYTHM\n    - Tech fest TECHSURGE\n    - Series tests (Feb, Mar, Apr)\n    - Project reviews\n    - End semester exams (Apr/May)', 124),

('hostel_discipline_rules', '125. Hostel Discipline & Rules', E'## 125. Hostel Discipline & Rules\n- **Curfew Timing:** 9:00 PM on weekdays, 10:00 PM on weekends\n- **Outpass System:** Required for leaving hostel\n- **Visitors:** Allowed in visitor rooms only, restricted timings\n- **Mess Timings:**\n    - Breakfast: 7:30-9:00 AM\n    - Lunch: 12:30-2:00 PM\n    - Snacks: 4:00-5:00 PM\n    - Dinner: 7:30-9:00 PM\n- **Room Inspection:** Regular inspections by warden\n- **Electricity Usage:** Restricted timing for high-power appliances', 125),

('campus_security', '126. Campus Security', E'## 126. Campus Security\n- **Security Personnel:** 24/7 presence at entry/exit points\n- **CCTV Surveillance:** Comprehensive coverage across campus\n- **Visitor Register:** Mandatory for all external visitors\n- **Vehicle Parking:** Separate parking for two-wheelers and four-wheelers\n- **Emergency Response:** Security trained for emergency situations\n- **Night Patrol:** Regular patrolling during night hours', 126),

('transportation_safety', '127. Transportation Safety', E'## 127. Transportation Safety\n- **Driver Training:** Professional drivers with valid licenses\n- **Vehicle Maintenance:** Regular servicing and fitness checks\n- **GPS Tracking:** Buses equipped with GPS\n- **Female Attendant:** Present in ladies'' buses\n- **Emergency Contact:** Bus coordinator contact shared with students\n- **Route Timings:** Strictly adhered to', 127),

('digital_learning_platforms', '128. Digital Learning Platforms', E'## 128. Digital Learning Platforms\n- **LMS (Learning Management System):** Online course materials\n- **Google Classroom:** Used by many faculty\n- **NPTEL:** Access to NPTEL courses\n- **Coursera/edX:** Institutional partnerships for certifications\n- **YouTube EDU:** Curated educational content\n- **Virtual Labs:** For remote practical learning', 128),

('assessment_evaluation_pattern', '129. Assessment & Evaluation Pattern', E'## 129. Assessment & Evaluation Pattern\n- **Continuous Internal Assessment (CIA):**\n    - CIA 1: 15 marks (Test + Assignment)\n    - CIA 2: 15 marks (Test + Seminar)\n    - CIA 3: 20 marks (Test + Attendance)\n    - Total Internal: 50 marks\n- **End Semester Exam:** 50 marks\n- **Total per Subject:** 100 marks\n- **Practical Evaluation:** Continuous + Final practical exam\n- **Project Evaluation:** Multiple reviews + final viva', 129),

('campus_recruitment_process', '130. Campus Recruitment Process', E'## 130. Campus Recruitment Process\n- **Pre-Placement Talk (PPT):** Company introduction\n- **Eligibility Criteria:** Based on CGPA, backlogs\n- **Aptitude Test:** Online/offline written test\n- **Group Discussion:** For some companies\n- **Technical Interview:** Subject knowledge assessment\n- **HR Interview:** Final round\n- **Offer Letter:** Issued post selection', 130),

('career_development_services', '131. Career Development Services', E'## 131. Career Development Services\n- **Resume Building:** Workshops conducted\n- **LinkedIn Profile:** Guidance for professional networking\n- **Mock Interviews:** Regular practice sessions\n- **Career Counseling:** One-on-one guidance\n- **Industry Talks:** Guest lectures by industry experts\n- **Certification Guidance:** For relevant technical certifications', 131),

('alumni_network_support', '132. Alumni Network & Support', E'## 132. Alumni Network & Support\n- **Alumni Portal:** Online platform for alumni\n- **Annual Alumni Meet:** Organized every year\n- **Alumni Mentorship:** Seniors guide juniors\n- **Job Referrals:** Alumni help in placements\n- **Guest Lectures:** Alumni share industry experience\n- **Funding Support:** Alumni contribute to scholarships', 132),

('international_student_support_if_applicable', '133. International Student Support (if applicable)', E'## 133. International Student Support (if applicable)\n- **Visa Assistance:** Guidance for foreign students\n- **Cultural Orientation:** Help with local adaptation\n- **Language Support:** Basic Malayalam/Hindi classes\n- **Special Mess Facilities:** International cuisine on request\n- **Festival Celebrations:** Inclusive environment', 133),

('differentlyabled_student_support', '134. Differently-abled Student Support', E'## 134. Differently-abled Student Support\n- **Saksham Scholarship:** AICTE scheme available\n- **Accessible Infrastructure:** Ramps, accessible washrooms\n- **Special Seating:** Preferential seating in class/exam halls\n- **Scribe Facility:** For visually impaired students\n- **Assistive Technology:** Screen readers, special keyboards\n- **Dedicated Support Staff:** For assistance when needed', 134),

('fee_refund_policy', '135. Fee Refund Policy', E'## 135. Fee Refund Policy\n- **Before Admission Confirmation:** Full refund minus processing fee\n- **After 15 days of Admission:** 50% refund\n- **After 30 days:** No refund of tuition fee\n- **Caution Deposit:** Refunded after course completion\n- **Hostel Fee:** Pro-rata refund if vacated mid-year', 135),

('transfer_migration', '136. Transfer & Migration', E'## 136. Transfer & Migration\n- **Transfer Certificate (TC):** Issued within 15 days of request\n- **Migration Certificate:** For students from other state boards\n- **No Objection Certificate (NOC):** Required for job/higher studies\n- **Course Completion Certificate:** Issued post final year\n- **Provisional Certificate:** Until original degree arrives', 136),

('scholarship_application_process', '137. Scholarship Application Process', E'## 137. Scholarship Application Process\n- **E-Grantz Portal:** Online application for SC/ST/OEC\n- **Documents Required:** Income certificate, caste certificate, bank details\n- **Deadline:** Usually September-October\n- **Verification:** College verifies and forwards\n- **Disbursement:** Directly to student bank account', 137),

('exam_fee_structure', '138. Exam Fee Structure', E'## 138. Exam Fee Structure\n- **Regular Exam Fee:** ₹600-800 per semester (approx.)\n- **Revaluation Fee:** ₹300-400 per subject\n- **Supplementary Exam Fee:** ₹500-700 per subject\n- **Thesis/Project Evaluation Fee:** ₹1000-1500\n- **Duplicate Mark Sheet:** ₹200-300', 138),

('id_card_student_records', '139. ID Card & Student Records', E'## 139. ID Card & Student Records\n- **ID Card Issue:** Within first month of joining\n- **Replacement Fee:** ₹200-300 for lost/damaged card\n- **Bonafide Certificate:** Free for students, issued on request\n- **Mark Sheets:** Issued after each semester\n- **Degree Certificate:** Original issued after convocation', 139),

('campus_facilities_advanced_details', '140. Campus Facilities: Advanced Details', E'## 140. Campus Facilities: Advanced Details\n- **Auditorium:** 500-seater capacity for events\n- **Seminar Halls:** Multiple halls with projection facilities\n- **Conference Room:** For meetings and video conferences\n- **Staff Rooms:** Department-wise faculty rooms\n- **Student Common Rooms:** Separate for boys and girls\n- **Medical Room:** First aid and basic treatment', 140),

('sports_facilities_equipment_coaching', '141. Sports Facilities: Equipment & Coaching', E'## 141. Sports Facilities: Equipment & Coaching\n- **Equipment Store:** Sports equipment available on request\n- **Coaching:** Professional coaches for major sports\n- **Tournaments:**\n    - Intra-college tournaments\n    - Inter-college participation\n    - University-level representation\n- **Annual Sports Day:** Typically in January/February\n- **Fitness Programs:** Yoga, aerobics sessions', 141),

('cultural_activities_detailed_clubs', '142. Cultural Activities: Detailed Clubs', E'## 142. Cultural Activities: Detailed Clubs\n- **Music Club:** Vocal, instrumental training\n- **Dance Club:** Classical, folk, western styles\n- **Drama Club:** Street plays, stage dramas\n- **Fine Arts Club:** Painting, sketching competitions\n- **Literary Club:** Debates, creative writing, book reviews\n- **Photography Club:** Photography workshops, exhibitions\n- **Quiz Club:** Regular quiz competitions\n- **Debate Society:** Parliamentary, Lincoln-Douglas debates', 142),

('technical_clubs_societies', '143. Technical Clubs & Societies', E'## 143. Technical Clubs & Societies\n- **Coding Club:** Competitive programming, hackathons\n- **Robotics Club:** Robot building, competitions\n- **Electronics Club:** DIY electronics projects\n- **Mechanical Innovation Club:** Design competitions\n- **Civil Engineering Society:** Site visits, technical talks\n- **Green Energy Club:** Renewable energy projects', 143),

('women_empowerment_initiatives', '144. Women Empowerment Initiatives', E'## 144. Women Empowerment Initiatives\n- **WOW (Women of Wonder):** Leadership, creativity\n- **Women Tech Makers (WTM):** Tech skills for women\n- **Self Defense Training:** Regular martial arts/self-defense classes\n- **Menstrual Hygiene Awareness:** Health camps\n- **Career Guidance for Women:** Special sessions\n- **Women''s Day Celebrations:** March 8th events', 144),

('innovation_patent_support', '145. Innovation & Patent Support', E'## 145. Innovation & Patent Support\n- **Patent Filing Assistance:** Guidance from R&D cell\n- **Prototype Development:** Makerspace support\n- **Funding for Innovation:** IEDC grants available\n- **IPR Awareness:** Workshops on intellectual property\n- **Product Development:** End-to-end support', 145),

('quality_assurance_iqac', '146. Quality Assurance (IQAC)', E'## 146. Quality Assurance (IQAC)\n- **Purpose:** Internal Quality Assurance Cell monitors standards\n- **Activities:**\n    - Curriculum feedback\n    - Faculty evaluation\n    - Infrastructure assessment\n    - Academic audits\n- **Accreditation:** Prepares for NAAC/NBA accreditations\n- **Best Practices:** Documents and promotes quality initiatives', 146),

('grievance_redressal_mechanism', '147. Grievance Redressal Mechanism', E'## 147. Grievance Redressal Mechanism\n- **Grievance Cell:** Headed by senior faculty\n- **Types of Grievances:**\n    - Academic issues\n    - Administrative matters\n    - Hostel problems\n    - Harassment complaints\n- **Process:** Written/online complaint → Investigation → Resolution\n- **Timeline:** Resolution within 15-30 days\n- **Appeal:** Can escalate to higher authorities', 147),

('antisexual_harassment_cell_internal_complaints_committee', '148. Anti-Sexual Harassment Cell (Internal Complaints Committee)', E'## 148. Anti-Sexual Harassment Cell (Internal Complaints Committee)\n- **Chairperson:** Senior female faculty member\n- **Members:** Mix of faculty, staff, external expert, student representative\n- **Confidentiality:** Complete privacy maintained\n- **Action:** Swift action as per law\n- **Awareness:** Regular workshops on gender sensitivity', 148),

('campus_connectivity_public_transport', '149. Campus Connectivity: Public Transport', E'## 149. Campus Connectivity: Public Transport\n- **Nearest Bus Stop:** Povval (1 km)\n- **Nearest Railway Station:** Kasaragod (12 km)\n- **Nearest Airport:** Mangalore International Airport (65 km)\n- **Local Transport:** Auto-rickshaws, taxis available\n- **College Buses:** 6 routes covering major areas', 149),

('nearby_facilities_offcampus', '150. Nearby Facilities (Off-Campus)', E'## 150. Nearby Facilities (Off-Campus)\n- **Hospitals:** District Hospital Kasaragod (12 km)\n- **Banks:** Multiple banks in Kasaragod town\n- **Restaurants:** Various eateries near campus and in town\n- **Shopping:** Kasaragod town market (12 km)\n- **Stationery Shops:** Available in Kasaragod town\n- **Photocopy Centers:** Available near campus', 150),

('faculty_development_programs_fdp', '151. Faculty Development Programs (FDP)', E'## 151. Faculty Development Programs (FDP)\n- **Regular FDPs:** Conducted by departments on emerging technologies\n- **AICTE-Sponsored FDPs:** National-level programs hosted\n- **Industry Collaborations:** FDPs with industry partners\n- **Online Courses:** Faculty encouraged to complete MOOCs\n- **Research Methodology:** Training for Ph.D. guides\n- **Pedagogy Workshops:** Teaching methodology improvements', 151),

('student_feedback_system', '152. Student Feedback System', E'## 152. Student Feedback System\n- **Course Feedback:** Collected at end of each semester\n- **Faculty Evaluation:** Anonymous student feedback\n- **Infrastructure Feedback:** Regular surveys\n- **Online Portal:** Digital feedback submission\n- **Action Taken:** Improvements based on feedback', 152),

('campus_it_infrastructure', '153. Campus IT Infrastructure', E'## 153. Campus IT Infrastructure\n- **Wi-Fi Coverage:** Entire campus covered\n- **Bandwidth:** 1 Gbps NKN connectivity\n- **Computer-Student Ratio:** 1:3 approximately\n- **Software Licenses:** Latest versions maintained\n- **E-Learning Tools:** LMS, video conferencing facilities\n- **IT Support Team:** Dedicated technical staff', 153),

('semester_registration_process', '154. Semester Registration Process', E'## 154. Semester Registration Process\n- **Online Registration:** Through college portal\n- **Subject Selection:** Choice-based credit system (if applicable)\n- **Fee Payment:** Online payment mandatory\n- **Course Confirmation:** After fee payment\n- **Late Registration:** Penalty charges applicable\n- **Withdrawal:** Within specified dates only', 154),

('academic_support_services', '155. Academic Support Services', E'## 155. Academic Support Services\n- **Remedial Classes:** For slow learners\n- **Advanced Learner Programs:** For high achievers\n- **Bridge Courses:** For lateral entry students\n- **Tutorial System:** Faculty tutors assigned\n- **Doubt Clearing Sessions:** Regular sessions\n- **Peer Learning:** Senior-junior interaction encouraged', 155),

('energy_sustainability_initiatives', '156. Energy & Sustainability Initiatives', E'## 156. Energy & Sustainability Initiatives\n- **LED Lighting:** Across campus\n- **Solar Panels:** Partial solar power generation\n- **Energy Audit:** Regular assessment\n- **Water Conservation:** Efficient usage monitored\n- **Green Building Norms:** Followed in new construction\n- **Carbon Footprint Reduction:** Ongoing efforts', 156),

('waste_management_system', '157. Waste Management System', E'## 157. Waste Management System\n- **Segregation:** Dry, wet, e-waste bins\n- **Biogas Plant:** For organic waste (if present)\n- **Recycling:** Paper, plastic recycling initiatives\n- **E-Waste Collection:** Periodic collection drives\n- **Awareness Campaigns:** Regular cleanliness drives', 157),

('campus_beautification', '158. Campus Beautification', E'## 158. Campus Beautification\n- **Landscaping:** Well-maintained gardens\n- **Herbal Garden:** Medicinal plants maintained\n- **Avenue Trees:** Lined along campus roads\n- **Flower Beds:** Seasonal flowers planted\n- **Eco-friendly Campus:** Plastic-free zones', 158),

('student_support_services', '159. Student Support Services', E'## 159. Student Support Services\n- **Counseling:** Academic, personal, career\n- **Financial Aid:** Scholarship guidance\n- **Health Services:** First aid, tie-ups with hospitals\n- **Legal Aid:** Basic legal awareness and support\n- **Disability Support:** Infrastructure and academic support', 159),

('final_remarks_future_plans', '160. Final Remarks & Future Plans', E'## 160. Final Remarks & Future Plans\n- **Vision 2030:** Aiming for autonomous status\n- **Infrastructure Expansion:** New blocks planned\n- **NAAC Accreditation:** Preparation underway\n- **International Collaborations:** More MOUs in pipeline\n- **Placement Target:** 90%+ placement rate goal\n- **Research Focus:** More funded projects and publications\n- **Startup Ecosystem:** Stronger incubation support', 160),

('vision_mission', '161. Vision & Mission', E'## 161. Vision & Mission\n- **Vision:** To become a paragon institution for pursuance of Education and Research in Engineering and Technology\n- **Mission:**\n  - Impart finest quality Technical Education & Training\n  - Nurture a vision of Sustainable development\n  - Bequeath it to the next generation of professionals', 161)
